import{_ as t,o as r,c as i,a2 as o}from"./chunks/framework.mrTIYZc5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DSO Documentation","text":"Secrets for Docker — Local to Cloud","tagline":"Inject secrets at runtime without storing them on disk. Use local encrypted vaults or cloud providers with the same workflow.","image":{"src":"/dso-logo.png","alt":"DSO Logo"},"actions":[{"theme":"brand","text":"Introduction","link":"/guide/what-is-dso"},{"theme":"alt","text":"Quickstart","link":"/guide/getting-started"}]},"features":[{"title":"Dual-Mode Execution","details":"Seamlessly switch between Local Mode (Native AES-256 Vault) and Cloud Mode (AWS, Azure, Huawei) with automatic detection.","icon":"⚡"},{"title":"Secret Isolation","details":"All secret values are held in-memory and injected via Unix socket. Zero persistence to disk as plaintext.","icon":"🔒"},{"title":"Verified Plugins","details":"Selective, SHA256-verified plugin installation. Only install what you need, with full integrity checks.","icon":"🛡️"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),a={name:"index.md"};function n(s,e,l,c,d,u){return r(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="why-dso" tabindex="-1">Why DSO? <a class="header-anchor" href="#why-dso" aria-label="Permalink to &quot;Why DSO?&quot;">​</a></h2><p>Docker Secret Operator (DSO) addresses a critical gap in infrastructure security: the management of sensitive credentials in non-Kubernetes environments. While Kubernetes has a mature ecosystem for secret orchestration, standalone Docker Engine deployments often rely on insecure <code>.env</code> files or manual, friction-heavy procedures.</p><p>DSO provides a <strong>Kubernetes-grade</strong> control loop for Docker Engine. It ensures that secrets are fetched from high-assurance vaults (like AWS Secrets Manager or HashiCorp Vault) and injected directly into target containers with <strong>Zero-Persistence</strong>. This means your secrets never touch the host filesystem, providing a strictly ephemeral and auditable lifecycle.</p><h3 id="core-security-pillars" tabindex="-1">Core Security Pillars: <a class="header-anchor" href="#core-security-pillars" aria-label="Permalink to &quot;Core Security Pillars:&quot;">​</a></h3><ul><li><strong>Zero Persistence</strong>: Secrets reside only in process RAM and target container memory-mapped filesystems.</li><li><strong>Event-Driven</strong>: Immediate reconciliation of container lifecycle events.</li><li><strong>Provider Agnostic</strong>: Standardized interface for AWS, Azure, Huawei Cloud, and HashiCorp Vault.</li><li><strong>Operations First</strong>: Built-in strategy engine for rolling updates and atomic shifts.</li></ul>',5)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
